import random


def strategy(history, rng):
    n = len(history)

    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    my_c = 0
    for a in me:
        if a == 'C':
            my_c += 1
    op_c = 0
    for a in op:
        if a == 'C':
            op_c += 1

    # Near the end, shift toward exploitation of cooperative partners.
    if n >= 97:
        if op_c >= n - max(2, n // 20):
            return 'D'
        if op[-1] == 'D':
            return 'D'
        return 'C'

    # Strongly cooperative opponent: keep CC alive, punish only clear exploitation.
    if op_c >= n - max(1, n // 12):
        if op[-1] == 'D':
            # Short punishment, then return to cooperation quickly.
            if n >= 2 and me[-1] == 'D' and op[-2] == 'D':
                return 'C'
            return 'D'
        # Rare probe only in mid-game with low probability.
        if n > 8 and n < 85 and rng.random() < 0.025:
            return 'D'
        return 'C'

    # Mostly defecting opponent: minimize losses, probe occasionally.
    if op_c <= n // 4:
        if op[-1] == 'C':
            return 'C'
        if me[-1] == 'D' and op[-1] == 'D':
            # Break DD deadlock occasionally.
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Mid-band: adaptive tit-for-tat with targeted forgiveness.
    last_me = me[-1]
    last_op = op[-1]

    # Detect recent patterns.
    window = min(8, n)
    recent_cc = 0
    recent_dd = 0
    recent_op_d = 0
    recent_me_d = 0
    for i in range(n - window, n):
        a = me[i]
        b = op[i]
        if a == 'C' and b == 'C':
            recent_cc += 1
        if a == 'D' and b == 'D':
            recent_dd += 1
        if b == 'D':
            recent_op_d += 1
        if a == 'D':
            recent_me_d += 1

    # If we are in a long mutual defection loop, cooperate to try to restore CC.
    if recent_dd >= 3 and recent_cc == 0:
        if rng.random() < 0.7:
            return 'C'

    # If opponent just defected but was largely cooperative recently, forgive.
    if last_op == 'D':
        if last_me == 'D':
            # We both defected; often one C can restart cooperation.
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        # We cooperated into a defection: retaliate, but forgive if isolated.
        if recent_op_d <= 1 and op_c * 3 >= n * 2:
            if rng.random() < 0.4:
                return 'C'
        return 'D'

    # Opponent cooperated last: mostly cooperate, small calculated probes.
    if recent_op_d >= 3 and recent_me_d >= 3:
        # Alternating retaliation pattern; try conciliatory move.
        if rng.random() < 0.35:
            return 'C'

    if n > 10 and n < 90 and rng.random() < 0.02:
        return 'D'
    return 'C'
